package entities

import (
	"slices"
	"strings"
)

const (
	// Marker opens every generated file.
	Marker = "# AUTOGENERATED by var-catalog from .terraform-var-catalog.hcl -- do not edit.\n" +
		"# Regenerate with the var-catalog runner (a consumer may wrap it in a make target)."
	// OutputName is the file generated in each stack, beside its own
	// `variables.tf` rather than appended to it: the order-check applies its
	// `// SET ON .HCL` / `// SET ON .ENV` marker rule to `variables.tf` only,
	// while its dead-input scan reads every `*.tf`, so generated declarations
	// stay out of a rule a generator cannot satisfy and in the gate that
	// matters.
	OutputName = "variables-shared.tf"
	// CatalogName is the consumer's catalog, at its repository root.
	CatalogName = ".terraform-var-catalog.hcl"
)

// Plan is what one stack gets: the catalogued names it uses and does not
// declare itself, and the ones it declares by hand -- preserved, never
// generated, because the local body may say something the canonical one does
// not, and a duplicate declaration is a hard Terraform error.
type Plan struct {
	Generate  []string
	Preserved []string
}

// PlanStack decides a stack's declarations from its own `.tf` sources -- the
// generated file left out -- in name order. A comment never counts as a use.
func PlanStack(sources []string, catalog Catalog) Plan {
	used := map[string]bool{}
	declared := map[string]bool{}
	for _, source := range sources {
		for _, name := range UsedVariables(StripComments(source)) {
			used[name] = true
		}
		for _, name := range DeclaredVariables(source) {
			declared[name] = true
		}
	}
	var plan Plan
	for _, name := range slices.Sorted(func(yield func(string) bool) {
		for name := range catalog {
			if used[name] && !yield(name) {
				return
			}
		}
	}) {
		if declared[name] {
			plan.Preserved = append(plan.Preserved, name)
		} else {
			plan.Generate = append(plan.Generate, name)
		}
	}
	return plan
}

// Render is the generated file for `names`: the marker, then each canonical
// body, a blank line between them. Nothing to generate is no file at all.
func Render(names []string, catalog Catalog) string {
	if len(names) == 0 {
		return ""
	}
	bodies := make([]string, len(names))
	for i, name := range names {
		bodies[i] = catalog[name]
	}
	return Marker + "\n\n" + strings.Join(bodies, "\n\n") + "\n"
}
